    "category": "行业新闻",
    "source": "[Connector Supplier](https://connectorsupplier.com/breaking-through-the-ai-power-wall/)",
    "summary": "AI数据中心的\"电源墙\"正成为行业最大瓶颈——全球数据中心耗电占全球总电1.5~2%，或达415TWh/年，2030年或近翻倍。连接器行业正通过降低接触电阻、改用800VDC供电、光互连替代铜互连（硅光/CPO）、兼容液冷等方式系统性降低功耗。光网络交换机市场预计2029年达$25亿。\n- **重要性**：🔥 连接器成为AI数据中心能效优化的关键变量\n\n---\n\n## 📊 中重要性",
