    "title": "后量子密码市场扩张，量子威胁逼近",
    "date": "2026-05-06",
    "category": "行业新闻",
    "source": "",
    "summary": "- **日期：** 2026年5月\n- **来源：** EE Times / Juniper Research\n- **摘要：** Juniper Research最新研究预测，后量子密码(PQC)市场将从2026年的12亿美元扩张到2035年的130亿美元，复合年增长率为30%。增长驱动力包括新兴法规和持续的研发投入，以应对\"Q-Day\"（量子计算机可能破解当前加密的那一天）。企业面临的主要风险是\"现在收割，以后解密\"策略，黑客今天收集加密数据，等待量子计算机成熟后再解密。\n- **链接：** https://www.eetimes.com/looming-quantum-threat-as",
    "link": "",
    "importance": "",
    "week_range": "** 2026年4月29日 - 2026年5月6日",
    "content": "- **日期：** 2026年5月\n- **来源：** EE Times / Juniper Research\n- **摘要：** Juniper Research最新研究预测，后量子密码(PQC)市场将从2026年的12亿美元扩张到2035年的130亿美元，复合年增长率为30%。增长驱动力包括新兴法规和持续的研发投入，以应对\"Q-Day\"（量子计算机可能破解当前加密的那一天）。企业面临的主要风险是\"现在收割，以后解密\"策略，黑客今天收集加密数据，等待量子计算机成熟后再解密。\n- **链接：** https://www.eetimes.com/looming-quantum-threat-as-pqc-market-expands/\n- **重要性：** ★★★★☆（安全领域，长期趋势）\n\n---"
