    "id": "news_2026-04-15_1",
    "title": "FCC拟全面禁止中国实验室为美国射频设备认证",
    "date": "2026-04-09",
    "category": "行业新闻",
    "source": "国际电子商情",
    "summary": "美国FCC宣布将于4月30日投票表决一项提案，拟全面禁止所有中国境内实验室为进入美国市场的射频类电子设备（智能手机、笔记本、IoT设备等）提供FCC标准检测与认证服务。此前FCC已通过\"不良实验室\"规则撤销超15家中国实验室资质，本次从\"黑名单\"升级为\"一刀切\"。提案含两年过渡期及\"信任实验室\"绿色通道，引导产业链转向美国本土或MRA签约国实验室。\n- **影响**：连接器企业出口美国产品的FCC认证流程将受影响，认证成本和周期可能增加。\n- **链接**：https://www.esmchina.com/news/14080.html\n\n---\n\n## 二、新产品 / 技术方案",
