    "title": "华为牵头OPEN NPO光互连MSA落地",
    "date": "2026-07-20",
    "category": "标准突破",
    "source": "综合报道",
    "summary": "国内首个近封装光学多源协议启动 华为联合中国移动研究院、百度、京东云、华工科技、光迅科技、华丰科技、立讯技术、Hirose、Molex等20余家产业链伙伴，在OAII社区会议上共同启动OPEN NPO项目，发起国内首个NPO光互连多源协议(MSA)。覆盖用户侧、算力设备、交换设备、光模块、电连接器、光电芯片、SerDes等全链路环节。NPO被视为可插拔光模块与CPO之间的过渡方案，功耗与时延优势显著、量产门槛更低。2027年上半年将推动规模化商用。",
