    "date": "2026-07-20",
    "category": "标准突破",
    "source": "综合报道",
    "summary": "在2026开放计算技术大会上，中航光电牵头编制的国内首部《吉瓦(GW)级开放智算中心框架技术报告》正式发布。报告搭建算力、高速互连、存储、高功率供电、全域液冷散热五大底层技术支柱。中航光电在高速互连板块围绕计算节点、交换节点、柜内柜间四类场景研判架构演进，阐释\"光铜并进、优势互补\"路线；在冷却板块系统拆解冷板式与浸没式液冷适配特点。这是继《智算中心高速互连技术白皮书(2026)》后再次为行业建立统一技术标尺。",
