    "summary": "224Gbps+薄型阴阳同体，185差分对高密度架构 Molex推出Gemini Mezz平行板连接器系列，提供紧凑、高速、高密度板对板连接，支持224Gbps+ PAM-4数据传输率。采用完全屏蔽差动信号线对(DP)、基于网格布局和薄型阴阳同体(自对配)设计，堆叠高度仅5mm，每平方英寸可容纳63个DP、总计185个DP。阴阳同体设计简化物料清单与库存管理，网格布局降低PCB布线复杂度与成本，面向AI数据中心、HPC与网络设备等高性能应用场景。",
