    "content": "由中国航空工业集团牵头，中航光电、航空工业综合所共同修订的ISO1966《飞机电缆压接接头》国际标准于7月10日正式发布。飞机电缆压接接头是飞机电气系统的核心连接部件，性能直接关系到飞行控制、航电通信、能源传输等机载关键系统的可靠性与安全性。新版标准将为全球航空电缆压接接头的研发、生产与检测提供权威、统一、适配现代航空装备发展的技术要求。"
