    "content": "汽车连接器大厂胡连8月6日宣布，通过旗下意大利子公司投资取得意大利电子线束与电缆系统专业制造商80%股权，标的对企业价值约576万欧元(约新台币2.14亿元)。董事会通过后授权董事长签约，预计今年10月支付价款、目标年内完成交割；资金来源为自有资金加银行借款，预估并购后每股盈余增加约0.29元。胡连过去超7成营收来自中国市场，主要客户含比亚迪、长安汽车、吉利、奇瑞等，此次并购意在满足欧洲垂直与横向整合的营运成长需要，跨足高端重机与顶级超跑供应链，并分散单一区域市场风险、提升国际市场营收比重与前端研发响应速度。在全球汽车产业变革(新能源车、自动驾驶用更多连接器)与欧洲车厂重塑供应链背景下，胡连从中国市场出发向国际发力。"
