    "content": "鼎通科技8月4日晚公告2026年半年报：上半年营收10.29亿元同比+31.17%，归母净利润1.84亿元同比+59.24%，扣非净利1.75亿元同比+62.73%；Q2营收5.72亿元(+40.86%)、净利1.03亿元(+65.50%)。业绩增长主要系通讯连接器市场需求旺盛、订单提升叠加新产品量产，高毛利通讯产品占比持续优化，综合毛利率升至33.98%(同比+5.72pct)。产品层面，112G高速连接器已进入大规模量产，面向数据中心与HPC的224G风冷产品实现规模化量产并切入客户新一代供应链；液冷相关产品上半年完成研发验证、Q2起放量明显，成为继高速连接器之后的第二核心成长曲线，公司已建成2条专业化液冷产线、订单饱满。汽车连接器业务短期受去库存与新能源供应链调整承压，公司仍聚焦高压与车载高速方向。经营现金流净额1.75亿元同比暴增866.78%，但财务费用因汇兑与借款同比大增、应收账款较年初+41.91%至7.09亿元，扩张期营运资金占用需关注。"
