    "content": "HARTING 8月3日确认，自8月4日起所有连接器、组件及配件系列涨价9%或以上，此前锁定订单维持原价，新订单执行新价。同期JST宣布自10月1日起连接器、压接端子及连续端子新订单重新定价，涨幅未公开，按客户协商执行并叠加汇率调整。本周市场监测显示，TE通信产品交期从约2个月延长至5个月以上且工厂配额生效；Molex Impel高速、Volfinity车载高压及224G系列交期持续拉长；TI服务器TPS高端现货溢价15%-40%。原材料成本上行与AI算力需求共振，连接器行业新一轮涨价潮正在蔓延。"
